const { projectName, target, deploymentId, files, framework, buildCommand, teamId } = $.input;
if (!projectName) throw new Error('projectName is required');

const body = { name: projectName };
if (target && target !== 'preview') body.target = target;
if (deploymentId) body.deploymentId = deploymentId;
if (files && files.length) body.files = files;

const projectSettings = {};
if (framework) projectSettings.framework = framework;
if (buildCommand) projectSettings.buildCommand = buildCommand;
if (Object.keys(projectSettings).length) body.projectSettings = projectSettings;

const params = {};
if (teamId) params.teamId = teamId;

return { body, params };

const resp = $.steps.createDeployment.response || {};
return {
  deploymentId: resp.id || '',
  url: resp.url || '',
  status: resp.status || resp.readyState || '',
  target: resp.target || 'preview',
  projectName: resp.name || $.input.projectName,
  aliases: resp.alias || [],
  regions: resp.regions || [],
  createdAt: resp.createdAt ? new Date(resp.createdAt).toISOString() : '',
  summary: resp.id ? `Deployment ${resp.id} created at ${resp.url || 'pending'} (${resp.status || resp.readyState || 'queued'})` : 'Failed to create deployment'
};
